mapper.select:
SELECT idCita, idPaciente, idMedico, idMedicoAnterior, fecha, hora, estado, observaciones
FROM cita
WHERE idCita = #{idCita}

SELECT idCita, idPaciente, idMedico, idMedicoAnterior, fecha, hora, estado, observaciones
FROM cita


        AND fecha = #{fecha}


        AND idPaciente = #{idPaciente}


        AND idMedico = #{idMedico}


        AND estado = #{estado}


ORDER BY fecha DESC, hora DESC
